(()=>{
 const coin=(x,label,kind='',c=['#16356f','#78a7fa','#2f70f2','white'])=>`<g class="pc-coin ${kind}" transform="translate(${x} 54)"><path d="M-12-24H12V-20H20V-12H24V12H20V20H12V24H-12V20H-20V12H-24V-12H-20V-20H-12Z" fill="${c[0]}" stroke="${c[1]}" stroke-width="2"/><path d="M-10-18H10V-14H16V-8H19V8H16V14H10V18H-10V14H-16V8H-19V-8H-16V-14H-10Z" fill="${c[2]}"/><text text-anchor="middle" x="0" y="7" fill="${c[3]}" font-family="Pixelify Sans,monospace" font-size="22">${label}</text></g>`;
 const arts={
 identity:`<rect x="29" y="13" width="182" height="82" fill="#0c1728" stroke="#36537c"/><path d="M29 31H211" stroke="#36537c"/><rect x="39" y="20" width="5" height="5" fill="#78a7fa"/><rect x="49" y="20" width="5" height="5" fill="#36537c"/><g class="pc-profile"><path d="M49 43H81V75H49Z" fill="#2758a2"/><path d="M55 69V49H61L65 57L69 49H75V69H69V59L65 65L61 59V69Z" fill="#e7f2ff"/></g><g fill="#4e76ad"><rect class="pc-line pc-line-a" x="95" y="47" width="83" height="5"/><rect class="pc-line pc-line-b" x="95" y="59" width="66" height="5"/><rect class="pc-line pc-line-c" x="95" y="71" width="91" height="5"/></g>`,
 mint:`<path d="M72 18H168V88H155V37H85V88H72Z" fill="#16376b" stroke="#638fd2" stroke-width="2"/><path d="M65 12H175V36H65Z" fill="#265db5" stroke="#91baff" stroke-width="2"/><text x="120" y="29" text-anchor="middle" fill="#e7f2ff" font-family="Pixelify Sans,monospace" font-size="12">STABLED</text><g class="pc-stamp"><rect x="114" y="37" width="12" height="15" fill="#426fae"/><rect x="96" y="50" width="48" height="9" fill="#8dbdff"/><rect x="100" y="59" width="40" height="6" fill="#3975d8"/></g><rect x="60" y="86" width="120" height="9" fill="#28548c" stroke="#638fd2"/><g class="pc-minted"><rect x="107" y="72" width="26" height="11" fill="#5289ee"/><rect x="111" y="69" width="18" height="4" fill="#b5d5ff"/></g><rect class="pc-flash" x="59" y="60" width="4" height="4" fill="#d5eaff"/><rect class="pc-flash" x="177" y="64" width="4" height="4" fill="#d5eaff"/>`,
 pair:`<path class="pc-flow" d="M55 54H185" stroke="#527ebd" stroke-width="2" stroke-dasharray="5 8"/>${coin(68,'M','pc-base')}${coin(172,'$','pc-quote',['#93b4ea','#e7f2ff','#e2ecff','#122b5a'])}<text x="68" y="99" text-anchor="middle" fill="#81a4d4" font-family="Pixelify Sans,monospace" font-size="10">YOUR COIN</text><text x="172" y="99" text-anchor="middle" fill="#81a4d4" font-family="Pixelify Sans,monospace" font-size="10">USDC</text>`,
 curve:`<path d="M30 92H170" stroke="#36537c"/><path d="M30 62H170M30 32H170" stroke="#1b2d45" stroke-dasharray="2 4"/>${[[38,80,8],[50,76,9],[62,78,6],[74,68,12],[86,62,11],[98,64,7],[110,50,16],[122,42,13],[134,34,12],[146,22,15],[158,14,12]].map(([x,y,h],i)=>`<g class="pc-candle" style="animation-delay:${i*.32}s"><rect x="${x+2}" y="${y-4}" width="1" height="${h+8}" fill="${i===2||i===5?'#ff7882':'#79a5ff'}"/><rect x="${x}" y="${y}" width="5" height="${h}" fill="${i===2||i===5?'#ff7882':'#79a5ff'}"/></g>`).join('')}<rect x="186" y="14" width="22" height="78" fill="#0b101a" stroke="#36537c"/><rect class="pc-fill" x="189" y="17" width="16" height="72" fill="#3678ff"/><rect class="pc-done" x="189" y="17" width="16" height="72" fill="#6ee7aa"/><text x="197" y="104" text-anchor="middle" fill="#81a4d4" font-family="Pixelify Sans,monospace" font-size="9">CURVE</text>`,
 rank:`<path d="M39 93H201" stroke="#36537c"/><g fill="#356dca"><rect class="pc-bar pc-bar-a" x="56" y="64" width="26" height="28"/><rect class="pc-bar pc-bar-b" x="107" y="49" width="26" height="43"/><rect class="pc-bar pc-bar-c" x="158" y="58" width="26" height="34"/></g><g class="pc-crown" fill="#a6c8ff"><path d="M103 21H110V27H116V16H124V27H130V21H137V37H103ZM106 40H134V44H106Z"/></g>`
 };
 // The looping strip under the hero: one row of facts, repeated once so the
 // scroll wraps without a seam. The copy is hidden from assistive technology.
 const px=(d,fill='#79a5ff',cls='')=>`<path class="${cls}" d="${d}" fill="${fill}"/>`;
 const icons={
  dollar:`<g class="lp-flip">${px('M9 3H23V5H27V9H29V23H27V27H23V29H9V27H5V23H3V9H5V5H9Z','#e2ecff')}${px('M15 7H17V9H21V11H13V15H21V23H17V25H15V23H11V21H19V17H11V9H15Z','#122b5a')}</g>`,
  press:`${px('M5 3H27V9H5Z','#265db5')}${px('M7 9H9V27H7ZM23 9H25V27H23ZM3 27H29V29H3Z','#36537c')}<g class="lp-press">${px('M15 9H17V13H15ZM10 13H22V16H10Z')}</g>`,
  zero:`${px('M5 7H13V9H15V23H13V25H5V23H3V9H5ZM7 11V21H11V11Z','#e2ecff')}<g class="lp-blink">${px('M19 7H23V11H19ZM25 21H29V25H25ZM27 7H29V9H27V11H25V13H23V17H21V21H19V25H21V23H23V19H25V15H27V11H29Z')}</g>`,
  wallet:`${px('M3 11H27V27H3Z','#16356f')}${px('M3 11H27V13H3ZM3 25H27V27H3ZM3 11H5V27H3ZM25 11H27V27H25Z')}${px('M19 17H29V21H19Z','#e2ecff')}<g class="lp-drop">${px('M11 1H17V3H19V7H17V9H11V7H9V3H11Z','#e2ecff')}</g>`,
  plus:`${px('M5 9H27V27H5Z','#16356f')}${px('M5 9H27V11H5ZM11 5H21V9H19V7H13V9H11Z')}<g class="lp-blink">${px('M15 13H17V17H21V19H17V23H15V19H11V17H15Z','#e2ecff')}</g>`,
  grad:`${px('M3 27H29V29H3Z','#36537c')}${px('M5 21H9V27H5Z','#36537c')}${px('M12 17H16V27H12Z','#3678ff')}${px('M19 11H23V27H19Z')}<g class="lp-rise">${px('M25 9H27V5H23V3H29V9Z','#6ee7aa')}</g>`,
  crown:`<g class="lp-rise">${px('M3 9H7V13H11V5H21V13H25V9H29V23H3ZM5 25H27V29H5Z','#a6c8ff')}</g>`,
  sol:`${px('M9 5H27V9H5V7H9ZM5 14H23V16H27V18H9V16H5ZM9 23H27V27H5V25H9Z')}<g class="lp-blink">${px('M27 12H29V14H27ZM3 20H5V22H3Z','#e2ecff')}</g>`
 };
 const facts=[['dollar','USDC pairs','Every price reads in dollars.'],['press','Launches on Pump','One wallet-signed transaction.'],['zero','No extra trading fee','Pump’s own schedule applies.'],['wallet','Creator fees to you','Your launch wallet is the creator.'],['plus','Optional developer buy','In USDC, inside the launch.'],['grad','Curve, then PumpSwap','A full curve opens the pool.'],['crown','King of memes','Top five-minute volume wins.'],['sol','SOL for the network','Rent and transaction fees only.']];
 const track=document.getElementById('loopTrack');
 if(track){
  const row=hidden=>`<ul class="loop-row"${hidden?' aria-hidden="true"':''}>${facts.map(([icon,title,text])=>`<li class="loop-card"><svg viewBox="0 0 32 32" shape-rendering="crispEdges" aria-hidden="true">${icons[icon]}</svg><div><b>${title}</b><span>${text}</span></div></li>`).join('')}</ul>`;
  track.innerHTML=row(false)+row(true);
 }
 document.querySelectorAll('[data-pixel-card]').forEach(el=>{const art=arts[el.dataset.pixelCard];if(art)el.innerHTML=`<svg viewBox="0 0 240 108" shape-rendering="crispEdges" aria-hidden="true">${art}</svg>`});
})();
